import heapq
from typing import List

def get_order_priorities(orderIds: List[int]) -> List[int]:
    v = orderIds
    n = len(v)
    prv = list(range(-1, n - 1))
    nxt = list(range(1, n + 1))
    alive = [True] * n

    def peak(i):
        return (alive[i] and (prv[i] < 0 or v[i] > v[prv[i]])
                and (nxt[i] >= n or v[i] > v[nxt[i]]))

    heap = [(v[i], i) for i in range(n) if peak(i)]
    heapq.heapify(heap)
    rest = sorted((v[i], i) for i in range(n))  # fallback for duplicates
    res = []
    while len(res) < n:
        while heap and not peak(heap[0][1]):
            heapq.heappop(heap)
        if heap:
            _, i = heapq.heappop(heap)
        else:
            i = next(j for _, j in rest if alive[j])
        res.append(v[i])
        alive[i] = False
        p, q = prv[i], nxt[i]
        if p >= 0:
            nxt[p] = q
        if q < n:
            prv[q] = p
        for j in (p, q):
            if 0 <= j < n and peak(j):
                heapq.heappush(heap, (v[j], j))
    return res
